"""Bahasa Melayu — tahap permulaan (200 soalan)."""

T = {
"prophets_251": ("Siapakah nama Nabi agama Islam?", ["Muhammad ﷺ", "Ibrahim", "Musa", "Isa"], "Nabi agama Islam ialah Muhammad ﷺ, anak Abdullah."),
"prophets_252": ("Ismail dan Ishak ialah anak nabi yang manakah?", ["Ibrahim", "Musa", "Nuh", "Daud"], "«Segala puji bagi Allah yang telah mengurniakan kepadaku, pada usia tua, Ismail dan Ishak» (14:39)."),
"prophets_253": ("Nabi manakah yang Allah angkat kepada-Nya?", ["Isa", "Yunus", "Ayub", "Idris"], "«Bahkan Allah telah mengangkatnya kepada-Nya» (4:158)."),
"prophets_254": ("Siapakah ibu Nabi Isa?", ["Maryam", "Asiah", "Hajar", "Sarah"], "Maryam, yang namanya diberikan kepada sebuah surah penuh dalam al-Quran."),
"prophets_255": ("Siapakah manusia pertama yang Allah ciptakan?", ["Adam", "Nuh", "Ibrahim", "Idris"], "Adam ialah manusia pertama, yang Allah ajarkan nama-nama segala sesuatu."),
"prophets_256": ("Bagi nabi manakah api menjadi sejuk dan selamat?", ["Ibrahim", "Musa", "Yusuf", "Sulaiman"], "«Wahai api, jadilah sejuk dan selamat bagi Ibrahim.»"),
"prophets_257": ("Nabi manakah yang membawa tongkat yang bertukar menjadi ular?", ["Musa", "Harun", "Yahya", "Zakaria"], "Allah bertanya kepada Musa: «Apakah itu di tangan kananmu?»"),
"prophets_258": ("Nabi manakah yang bermimpi melihat sebelas bintang sujud?", ["Yusuf", "Yaakub", "Ishak", "Daud"], "«Wahai ayahku, aku melihat sebelas bintang, matahari dan bulan.»"),
"prophets_259": ("Burung manakah yang membawa berita kepada Nabi Sulaiman?", ["Burung hud-hud", "Burung gagak", "Burung helang", "Burung merpati"], "Burung hud-hud berkata: «Aku datang kepadamu dari Saba' membawa berita yang pasti» (27:22)."),
"prophets_260": ("Nabi manakah yang menjadi teladan kesabaran dalam ujian?", ["Ayub", "Yunus", "Lut", "Syuaib"], "Ayub menyeru Tuhannya dan didapati tabah bersabar."),
"prophets_261": ("Daripada apakah Allah menciptakan Adam?", ["Daripada tanah", "Daripada cahaya", "Daripada api", "Daripada angin"], "«Dia menciptakannya daripada tanah, kemudian berfirman kepadanya: Jadilah!» (3:59)."),
"prophets_262": ("Nabi manakah yang Allah ajak bicara secara langsung?", ["Musa", "Yusuf", "Yunus", "Salih"], "«Dan Allah telah berbicara kepada Musa secara langsung.»"),
"prophets_263": ("Berapakah bilangan nabi yang datang selepas Muhammad ﷺ?", ["Tiada: baginda ialah nabi yang terakhir", "Seorang", "Tiga orang", "Tujuh orang"], "Muhammad ﷺ ialah penutup para nabi: tiada nabi selepas baginda."),
"prophets_264": ("Nabi manakah yang digelar sahabat karib (khalil) Allah?", ["Ibrahim", "Musa", "Isa", "Nuh"], "Ibrahim ialah bapa para nabi dan sahabat karib Yang Maha Pemurah."),
"prophets_265": ("Nabi manakah yang menyembuhkan orang buta sejak lahir dengan izin Allah?", ["Isa", "Yahya", "Zakaria", "Ilyas"], "«Dan engkau menyembuhkan orang yang buta sejak lahir dan orang yang berpenyakit kusta dengan izin-Ku.»"),
"prophets_266": ("Bagi nabi manakah gunung-ganang turut bertasbih memuji Allah?", ["Daud", "Sulaiman", "Ayub", "Yunus"], "«Wahai gunung-ganang, ulangilah tasbih memuji Allah bersamanya.»"),
"prophets_267": ("Nabi manakah yang mentafsirkan mimpi raja Mesir?", ["Yusuf", "Harun", "Ilyas", "Syuaib"], "Yusuf mentafsirkan mimpi tujuh ekor lembu gemuk dan tujuh ekor lembu kurus (12:46-49)."),
"prophets_268": ("Siapakah bapa Nabi Yusuf?", ["Yaakub", "Ishak", "Ibrahim", "Lut"], "Yusuf ialah anak Yaakub, dan Yaakub pula anak Ishak."),
"prophets_269": ("Apakah yang terbelah di hadapan Musa dan kaumnya?", ["Laut, terbelah untuk menyelamatkan mereka daripada Firaun", "Sebatang sungai di Mesir", "Sebuah tasik di Madyan", "Sebuah perigi di padang pasir"], "«Dan ketika Kami membelah laut untuk kamu, lalu Kami selamatkan kamu.»"),
"prophets_270": ("Apakah yang diucapkan selepas menyebut nama Nabi ﷺ?", ["«Semoga Allah melimpahkan selawat dan salam ke atasnya»", "Tiada apa-apa yang khusus", "«Terima kasih»", "«Selamat tinggal»"], "Kita berselawat dan mengucapkan salam ke atas baginda: sallallahu 'alaihi wa sallam."),
"prophets_271": ("Nabi manakah yang menyeru kaumnya untuk tempoh yang sangat lama sebelum banjir besar?", ["Nuh", "Hud", "Salih", "Syuaib"], "«Kami mengutus Nuh kepada kaumnya: berilah peringatan kepada kaummu.»"),
"prophets_272": ("Sulaiman ialah anak nabi yang manakah?", ["Daud", "Yaakub", "Ishak", "Yunus"], "«Dan Kami kurniakan kepada Daud, Sulaiman — sebaik-baik hamba!» (38:30)."),
"prophets_273": ("Nabi manakah yang mengalahkan Jalut (Goliath)?", ["Daud", "Sulaiman", "Yusya'", "Ilyas"], "«Dan Daud membunuh Jalut» (2:251)."),
"prophets_274": ("Berapa ramai nabi yang wajib diimani seorang Muslim?", ["Semuanya, tanpa membeza-bezakan", "Hanya yang terakhir", "Hanya tiga orang", "Hanya yang disebut dalam al-Quran"], "Seorang Muslim beriman kepada semua nabi Allah, tanpa membeza-bezakan antara mereka."),
"prophets_275": ("Siapakah yang Allah pilih, menurut al-Quran?", ["Adam, Nuh, keluarga Ibrahim dan keluarga 'Imran", "Raja-raja Mesir", "Kabilah-kabilah Madinah", "Kaum Saba'"], "«Sesungguhnya Allah telah memilih Adam, Nuh, keluarga Ibrahim dan keluarga 'Imran.»"),
"prophets_276": ("Di negeri manakah Nabi Yusuf menjadi orang kepercayaan raja?", ["Mesir", "Syam", "Yaman", "Iraq"], "Yusuf diberi kedudukan di Mesir selepas mentafsirkan mimpi raja."),
"prophets_277": ("Nabi manakah yang dibawa pada waktu malam ke Masjid al-Aqsa?", ["Muhammad ﷺ", "Musa", "Isa", "Ibrahim"], "«Maha Suci Allah yang telah memperjalankan hamba-Nya pada waktu malam.»"),
"prophets_278": ("Kitab apakah yang diberikan kepada Nabi Musa?", ["Taurat", "Injil", "Zabur", "Suhuf Ibrahim"], "Allah memberikan Kitab kepada Musa, dan mengutus para rasul selepasnya."),
"prophets_279": ("Kitab apakah yang diberikan kepada Nabi Isa?", ["Injil", "Taurat", "Zabur", "Al-Quran"], "«Dan Kami berikan kepadanya Injil, yang di dalamnya ada petunjuk dan cahaya.»"),
"prophets_280": ("Kitab apakah yang diberikan kepada Nabi Daud?", ["Zabur", "Taurat", "Injil", "Suhuf Musa"], "«Dan Kami berikan Zabur kepada Daud.»"),
"prophets_281": ("Anak nabi manakah yang rela dikorbankan kerana taat kepada Allah?", ["Anak Ibrahim", "Anak Nuh", "Saudara Musa", "Anak Yaakub"], "«Wahai ayahku, lakukanlah apa yang diperintahkan kepadamu: engkau akan mendapati aku termasuk orang yang sabar.»"),
"prophets_282": ("Di manakah ibu Musa meletakkan bayinya untuk menyelamatkannya?", ["Di sungai", "Di dalam gua", "Di rumah jiran", "Di padang pasir"], "«Campakkanlah dia ke dalam sungai: Kami akan mengembalikannya kepadamu.»"),
"prophets_283": ("Apakah yang diucapkan Yunus dalam kegelapan, yang diulang oleh setiap Muslim?", ["«Tiada tuhan selain Engkau, Maha Suci Engkau, sesungguhnya aku termasuk orang yang zalim»", "«Berikanlah aku kekayaan»", "«Jadikanlah aku raja»", "«Jadikanlah aku kuat»"], "Doa Yunus di dalam perut ikan."),
"prophets_284": ("Siapakah bapa Nabi Muhammad ﷺ?", ["Abdullah", "Abu Talib", "Al-Abbas", "Hamzah"], "Baginda ialah Muhammad ﷺ, anak Abdullah, anak Abdul Muttalib."),
"prophets_285": ("Siapakah ibu Nabi Muhammad ﷺ?", ["Aminah", "Khadijah", "Aisyah", "Fatimah"], "Aminah binti Wahab ialah ibu Nabi ﷺ."),
"prophets_286": ("Apakah yang dikatakan Isa ketika masih dalam buaian?", ["«Aku hamba Allah»", "«Aku seorang raja»", "«Aku malaikat»", "Dia tidak berkata apa-apa"], "«Sesungguhnya aku hamba Allah: Dia telah memberiku Kitab.»"),
"prophets_287": ("Nabi manakah yang diutus kepada kaum 'Ad?", ["Hud", "Salih", "Lut", "Syuaib"], "«Dan kepada kaum 'Ad, saudara mereka Hud.»"),
"prophets_288": ("Nabi manakah yang diutus kepada kaum Tsamud, bersama unta betina?", ["Salih", "Hud", "Yunus", "Idris"], "«Dan kepada kaum Tsamud, saudara mereka Salih: inilah unta betina Allah.»"),
"prophets_289": ("Nabi manakah saudara Musa, yang diutus bersamanya?", ["Harun", "Yusuf", "Yahya", "Ilyas"], "«Dan jadikanlah untukku seorang pembantu daripada keluargaku: Harun, saudaraku.»"),
"prophets_290": ("Apakah gelaran yang al-Quran berikan kepada Muhammad ﷺ berkaitan para nabi?", ["Penutup para nabi", "Nabi yang pertama", "Raja para nabi", "Jurutulis para nabi"], "«Muhammad ialah Rasul Allah dan penutup para nabi.»"),
"prophets_291": ("Apakah yang dikatakan para malaikat kepada Maryam dalam al-Quran?", ["Bahawa Allah telah memilih dan menyucikannya", "Bahawa dia akan menjadi ratu", "Bahawa dia akan mengembara", "Bahawa dia akan mengajar"], "«Wahai Maryam, sesungguhnya Allah telah memilihmu dan menyucikanmu.»"),
"prophets_292": ("Bagaimanakah Ayub menyeru Tuhannya dalam ujiannya?", ["«Aku ditimpa kesusahan, dan Engkaulah Yang Maha Penyayang»", "«Jadikanlah aku kaya»", "«Hukumlah musuh-musuhku»", "«Jadikanlah aku raja»"], "«Sesungguhnya aku ditimpa kesusahan, dan Engkaulah Yang Maha Penyayang di antara para penyayang.»"),
"prophets_293": ("Apakah yang Allah ajarkan kepada Adam?", ["Nama-nama segala sesuatu", "Menulis", "Ilmu pelayaran", "Ilmu hisab"], "«Dan Dia mengajarkan kepada Adam nama-nama segala sesuatu.»"),
"prophets_294": ("Nabi manakah yang memerintah kerajaan yang tidak akan dimiliki sesiapa selepasnya?", ["Sulaiman", "Daud", "Yusuf", "Zulkarnain"], "«Kurniakanlah kepadaku kerajaan yang tidak dimiliki oleh sesiapa pun selepasku.»"),
"prophets_295": ("Nabi manakah yang diselamatkan bersama keluarganya, kecuali isterinya?", ["Lut", "Nuh", "Hud", "Salih"], "«Berjalanlah bersama keluargamu pada sebahagian malam… kecuali isterimu.»"),
"prophets_296": ("Apakah yang Ibrahim peringatkan kepada kaumnya supaya dijauhi?", ["Menyembah berhala", "Berniaga", "Mengembara", "Menulis"], "«Adakah engkau menjadikan berhala-berhala sebagai tuhan?»"),
"prophets_297": ("Perkataan manakah yang bermaksud orang yang diutus Allah kepada manusia?", ["Rasul", "Khalifah", "Sahabat", "Ulama"], "Rasul ialah orang yang diutus Allah, yang diamanahkan menyampaikan risalah kepada manusia."),
"prophets_298": ("Sebagai apakah Allah mengutus Nabi ﷺ, menurut Surah Al-Ahzab?", ["Saksi, pembawa berita gembira dan pemberi peringatan", "Raja dan hakim", "Pedagang", "Penyair"], "«Wahai Nabi, sesungguhnya Kami mengutusmu sebagai saksi, pembawa berita gembira dan pemberi peringatan» (33:45)."),
"prophets_299": ("Mengapakah Muhammad ﷺ diutus, menurut al-Quran?", ["Sebagai rahmat bagi sekalian alam", "Untuk memerintah", "Untuk membina", "Untuk berniaga"], "«Dan Kami tidak mengutusmu melainkan sebagai rahmat bagi sekalian alam.»"),
"prophets_300": ("Nabi manakah yang al-Quran gelar «hamba yang banyak bersyukur»?", ["Nuh", "Lut", "Idris", "Ilyas"], "«Sesungguhnya dia adalah hamba yang banyak bersyukur» (17:3), tentang Nuh."),
"prophets_301": ("Apakah tanda yang diberikan kepada Zakaria selepas berita gembira tentang anaknya?", ["Tidak bercakap dengan manusia selama tiga hari", "Melihat sebuah bintang", "Mendengar guruh", "Berjalan di atas air"], "«Tandanya ialah engkau tidak bercakap dengan manusia selama tiga hari» (3:41)."),
"prophets_302": ("Dalam bahasa apakah setiap rasul diutus?", ["Dalam bahasa kaumnya sendiri", "Dalam bahasa Arab sahaja", "Dalam bahasa Ibrani", "Dalam bahasa langit"], "«Kami tidak mengutus seorang rasul pun melainkan dengan bahasa kaumnya.»"),
"prophets_303": ("Surah manakah yang menceritakan kisah seorang nabi dari awal hingga akhir?", ["Surah Yusuf", "Surah Al-Baqarah", "Surah An-Nas", "Surah Al-Fatihah"], "«Kami menceritakan kepadamu kisah yang paling baik» — kisah Yusuf."),
"prophets_304": ("Bagaimanakah al-Quran menggambarkan Ibrahim dalam Surah Maryam?", ["Seorang yang sangat benar, seorang nabi", "Seorang raja", "Seorang jurutulis", "Seorang pedagang"], "«Sesungguhnya dia seorang yang sangat benar, seorang nabi.»"),
"prophets_305": ("Ratu manakah yang datang menemui Nabi Sulaiman?", ["Ratu Saba'", "Ratu Mesir", "Ratu Babylon", "Ratu Yaman utara"], "Dia berserah diri bersama Sulaiman kepada Allah, Tuhan sekalian alam."),
"prophets_306": ("Nabi manakah yang meminta untuk melihat bagaimana Allah menghidupkan semula yang mati?", ["Ibrahim", "Musa", "Nuh", "Yunus"], "«Wahai Tuhanku, tunjukkanlah kepadaku bagaimana Engkau menghidupkan orang mati.»"),
"prophets_307": ("Nabi manakah yang mengembara untuk belajar daripada seorang hamba yang berilmu?", ["Musa", "Yusuf", "Daud", "Sulaiman"], "Musa berjalan sehingga bertemu seorang hamba Allah yang telah dikurniakan ilmu."),
"prophets_308": ("Apakah yang diajarkan Surah Al-Ikhlas tentang Allah?", ["Bahawa Dia Maha Esa, dan tiada sesiapa yang setara dengan-Nya", "Bahawa Dia mempunyai sekutu", "Bahawa Dia menyerupai makhluk-Nya", "Bahawa Dia mempunyai anak"], "«Katakanlah: Dialah Allah, Yang Maha Esa… dan tiada sesiapa pun yang setara dengan-Nya.»"),
"prophets_309": ("Apakah gelaran yang diberikan penduduk Makkah kepada Nabi ﷺ sebelum wahyu?", ["Al-Amin, yang dipercayai", "Pengembara", "Penyair", "Hakim"], "Kejujuran baginda begitu terkenal sehingga baginda digelar al-Amin."),
"prophets_310": ("Siapakah yang al-Quran kemukakan sebagai teladan terbaik untuk diikuti?", ["Rasulullah ﷺ", "Raja-raja", "Para penyair", "Para pedagang"], "«Sesungguhnya telah ada pada diri Rasulullah teladan yang baik bagi kamu.»"),
"sira_251": ("Di kota manakah Nabi ﷺ dilahirkan?", ["Makkah", "Madinah", "Baitulmaqdis", "Ta'if"], "Nabi ﷺ dilahirkan di Makkah, dalam kabilah Quraisy."),
"sira_252": ("Ke kota manakah Nabi ﷺ berhijrah?", ["Madinah", "Ta'if", "Kaherah", "Damsyik"], "Hijrah berlaku dari Makkah ke Madinah, yang ketika itu dinamakan Yathrib."),
"sira_253": ("Apakah nama perpindahan dari Makkah ke Madinah?", ["Hijrah", "Haji", "Pembukaan", "Perjanjian"], "Hijrah menandakan permulaan kalendar Islam."),
"sira_254": ("Siapakah isteri pertama Nabi ﷺ?", ["Khadijah", "Aisyah", "Hafsah", "Saudah"], "Khadijah binti Khuwailid, orang pertama yang beriman kepada baginda."),
"sira_255": ("Di gua manakah Nabi ﷺ bersembunyi semasa Hijrah?", ["Gua Tsur", "Gua Hira", "Gua Uhud", "Gua Quba'"], "Baginda bersembunyi di situ selama tiga hari bersama Abu Bakar sebelum meneruskan perjalanan ke Madinah."),
"sira_256": ("Apakah perkataan pertama yang diwahyukan kepada Nabi ﷺ?", ["«Bacalah»", "«Solatlah»", "«Bangunlah»", "«Dengarlah»"], "«Bacalah dengan nama Tuhanmu yang menciptakan.»"),
"sira_257": ("Malaikat manakah yang membawa wahyu kepada Nabi ﷺ?", ["Jibril", "Mikail", "Israfil", "Malik"], "Jibril ialah malaikat yang ditugaskan menurunkan wahyu."),
"sira_258": ("Di kota manakah terletaknya makam Nabi ﷺ?", ["Madinah", "Makkah", "Baitulmaqdis", "Ta'if"], "Makam baginda terletak di Madinah, di sisi masjidnya."),
"sira_259": ("Daripada kabilah manakah Nabi ﷺ berasal?", ["Quraisy", "Aus", "Khazraj", "Thaqif"], "Nabi ﷺ berasal daripada Quraisy, kabilah Makkah."),
"sira_260": ("Apakah nama bagi para pengikut yang hidup bersama Nabi ﷺ?", ["Sahabat", "Tabi'in", "Ansar sahaja", "Qurra'"], "Sahabat ialah mereka yang melihat Nabi ﷺ dalam keadaan beriman kepada baginda."),
"sira_261": ("Siapakah yang menemani Nabi ﷺ semasa Hijrah?", ["Abu Bakar", "Umar", "Uthman", "Bilal"], "Abu Bakar ialah teman baginda di dalam gua semasa Hijrah."),
"sira_262": ("Siapakah muazin Nabi ﷺ?", ["Bilal", "Anas", "Zaid", "Salman"], "Bilal bin Rabah melaungkan azan di Madinah."),
"sira_263": ("Apakah nama peperangan pertama dalam Islam?", ["Badar", "Uhud", "Khaibar", "Hunain"], "Badar ialah peperangan besar yang pertama, pada tahun kedua Hijrah."),
"sira_264": ("Apakah nama bagi mereka yang berhijrah dari Makkah ke Madinah?", ["Muhajirin", "Ansar", "Tabi'in", "Sahabat Ta'if"], "Muhajirin ialah orang yang berhijrah; Ansar ialah mereka yang menyambut kedatangan mereka."),
"sira_265": ("Apakah nama bagi penduduk Madinah yang menyambut orang yang berhijrah?", ["Ansar", "Muhajirin", "Quraisy", "Tabi'in"], "Ansar, «para penolong», ialah kaum Aus dan Khazraj di Madinah."),
"sira_266": ("Apakah yang mula-mula dibina Nabi ﷺ di Madinah?", ["Masjid", "Pasar", "Istana", "Tembok"], "Baginda membina masjidnya sebaik sahaja tiba di Madinah."),
"sira_267": ("Anak perempuan Nabi ﷺ yang manakah berkahwin dengan Ali?", ["Fatimah", "Ruqayyah", "Zainab", "Ummu Kalthum"], "Fatimah, anak Nabi ﷺ, berkahwin dengan Ali bin Abi Talib."),
"sira_268": ("Siapakah khalifah pertama selepas Nabi ﷺ?", ["Abu Bakar", "Umar", "Uthman", "Ali"], "Abu Bakar as-Siddiq ialah khalifah yang pertama."),
"sira_269": ("Apakah nama Madinah sebelum itu?", ["Yathrib", "Bakkah", "Ta'if", "Khaibar"], "Yathrib mengambil nama Madinatun Nabi, kota Nabi ﷺ."),
"sira_270": ("Berapakah umur Nabi ﷺ ketika menerima wahyu pertama?", ["Empat puluh tahun", "Dua puluh tahun", "Enam puluh tahun", "Tiga puluh tahun"], "Wahyu datang kepada baginda ketika baginda berusia empat puluh tahun."),
"sira_271": ("Di kota manakah terletaknya Kaabah?", ["Makkah", "Madinah", "Baitulmaqdis", "Damsyik"], "Kaabah terletak di tengah-tengah Masjidil Haram, di Makkah."),
"sira_272": ("Di kota manakah terletaknya Masjid al-Aqsa?", ["Baitulmaqdis", "Makkah", "Madinah", "Kaherah"], "Masjid al-Aqsa terletak di Baitulmaqdis (al-Quds)."),
"sira_273": ("Bapa saudara Nabi ﷺ yang manakah melindungi baginda di Makkah?", ["Abu Talib", "Abu Lahab", "Al-Abbas", "Abu Sufyan"], "Abu Talib, bapa Ali, melindungi anak saudaranya daripada Quraisy."),
"sira_274": ("Apakah pekerjaan Khadijah, isteri pertama Nabi ﷺ?", ["Peniaga", "Doktor", "Penyair", "Penenun"], "Khadijah ialah seorang peniaga yang dihormati di Makkah."),
"sira_275": ("Apakah nama haji terakhir Nabi ﷺ?", ["Haji Perpisahan (Hajjatul Wada')", "Haji yang pertama", "Haji pembukaan", "Haji kecil"], "Haji Perpisahan berlaku pada tahun ke-10 Hijrah."),
"sira_276": ("Apakah nama bagi riwayat hidup Nabi ﷺ?", ["Sirah", "Sunnah", "Tafsir", "Fiqh"], "Sirah ialah riwayat hidup baginda; Sunnah ialah apa yang baginda katakan dan lakukan."),
"sira_277": ("Apakah nama bagi ucapan yang diriwayatkan daripada Nabi ﷺ?", ["Hadis", "Surah", "Ayat", "Doa"], "Hadis ialah ucapan, perbuatan atau perakuan Nabi ﷺ."),
"sira_278": ("Apakah dua kitab himpunan hadis yang dianggap paling sahih?", ["Sahih al-Bukhari dan Sahih Muslim", "Dua himpunan puisi", "Dua buku sejarah", "Dua buah kamus"], "Kedua-duanya dinamakan bersama «dua kitab Sahih»."),
"sira_279": ("Khalifah manakah yang menyalin al-Quran dan menghantarnya ke wilayah-wilayah?", ["Uthman", "Abu Bakar", "Umar", "Ali"], "Uthman menyediakan naskhah rasmi dan menghantarnya ke kota-kota utama."),
"sira_280": ("Berapakah bilangan «Khulafa' ar-Rasyidin», khalifah yang mendapat petunjuk?", ["Empat", "Dua", "Tujuh", "Dua belas"], "Abu Bakar, Umar, Uthman dan Ali."),
"sira_281": ("Ke arah manakah orang Islam menghadap ketika solat?", ["Ke arah Kaabah, di Makkah", "Ke arah Baitulmaqdis", "Ke arah timur", "Ke arah Madinah"], "Kiblat ialah arah Kaabah."),
"sira_282": ("Apakah nama bagi arah solat itu?", ["Kiblat", "Mihrab", "Mimbar", "Menara"], "Kiblat ialah arahnya; mihrab ialah ceruk yang menandakannya."),
"sira_283": ("Apakah nama tempat orang Islam solat bersama-sama?", ["Masjid", "Sekolah", "Pasar", "Perpustakaan"], "Masjid ialah tempat sujud, iaitu rumah ibadat orang Islam."),
"sira_284": ("Apakah nama seruan untuk solat?", ["Azan", "Takbir", "Tasbih", "Zikir"], "Azan ialah seruan; orang yang melaungkannya ialah muazin."),
"sira_285": ("Pada hari apakah orang Islam berhimpun untuk solat besar?", ["Jumaat", "Sabtu", "Ahad", "Isnin"], "Solat Jumaat (al-jumu'ah) menghimpunkan umat setiap minggu."),
"sira_286": ("Apakah nama orang yang memimpin solat?", ["Imam", "Muazin", "Kadi", "Hafiz"], "Imam ialah orang yang jemaah berbaris di belakangnya untuk solat."),
"sira_287": ("Apakah nama bagi orang yang menghafaz seluruh al-Quran?", ["Hafiz", "Imam", "Muazin", "Kadi"], "Hafiz ialah orang yang menyimpan seluruh al-Quran dalam ingatannya."),
"sira_288": ("Sahabat manakah yang dikenali sebagai perawi hadis yang paling banyak?", ["Abu Hurairah", "Bilal", "Salman", "Anas"], "Abu Hurairah menghabiskan tahun-tahun terakhir Nabi ﷺ di sisi baginda."),
"sira_289": ("Khalifah manakah yang digelar as-Siddiq, «yang membenarkan»?", ["Abu Bakar", "Umar", "Uthman", "Ali"], "Abu Bakar as-Siddiq, lelaki merdeka pertama yang beriman."),
"sira_290": ("Khalifah manakah yang digelar al-Faruq?", ["Umar bin al-Khattab", "Abu Bakar", "Uthman", "Ali"], "Umar, yang membezakan antara yang benar dan yang batil, menerima gelaran itu."),
"sira_291": ("Khalifah manakah yang menghimpunkan al-Quran dalam satu mushaf?", ["Abu Bakar", "Mu'awiyah", "Khalid", "Bilal"], "Abu Bakar memerintahkan agar apa yang telah ditulis dihimpunkan bersama."),
"sira_292": ("Datuk manakah yang membesarkan Nabi ﷺ ketika kecil?", ["Abdul Muttalib", "Abu Sufyan", "Al-Walid", "'Utbah"], "Datuknya Abdul Muttalib mengambil tanggungjawab menjaga baginda sejak kelahirannya."),
"sira_293": ("Bagaimanakah al-Quran mengingatkan zaman kanak-kanak Nabi ﷺ?", ["Allah mendapatinya yatim lalu memberinya perlindungan", "Baginda seorang raja", "Baginda kaya sejak kecil", "Baginda hidup seorang diri di padang pasir"], "«Bukankah Dia mendapatimu seorang yatim, lalu Dia melindungimu?» (93:6)."),
"sira_294": ("Peperangan manakah yang berlaku selepas Badar?", ["Uhud", "Khandak", "Hunain", "Tabuk"], "Pada tahun berikutnya berlaku Perang Uhud, berhampiran Madinah."),
"sira_295": ("Apakah yang digali orang Islam di sekeliling Madinah untuk mempertahankannya?", ["Parit (al-Khandak)", "Perigi", "Terowong", "Terusan"], "Mereka menggali parit, yang menjadi asal nama Perang Khandak."),
"sira_296": ("Aisyah, isteri Nabi ﷺ, ialah anak kepada siapa?", ["Abu Bakar", "Umar", "Uthman", "Ali"], "Aisyah ialah anak Abu Bakar as-Siddiq."),
"sira_297": ("Apakah gelaran al-Quran bagi isteri-isteri Nabi ﷺ?", ["Ibu orang-orang beriman", "Hamba-hamba", "Teman perjalanan", "Wanita yang berhijrah"], "«Dan isteri-isterinya adalah ibu mereka» (33:6)."),
"sira_298": ("Sahabat manakah yang merupakan sepupu dan juga menantu Nabi ﷺ?", ["Ali bin Abi Talib", "Bilal", "Salman", "Zaid"], "Ali, sepupu Nabi ﷺ, berkahwin dengan anak baginda, Fatimah."),
"sira_299": ("Apakah nama masjid Nabi ﷺ di Madinah?", ["Masjid Nabawi", "Masjidil Haram", "Masjid al-Aqsa", "Masjid Quba'"], "Masjid Nabi, iaitu Masjid Nabawi, terletak di Madinah."),
"sira_300": ("Apakah nama tunggangan Nabi ﷺ dalam perjalanan malam (Isra')?", ["Al-Buraq", "Al-'Adba'", "Asy-Syaqra'", "Al-Qaswa'"], "Tunggangan dalam perjalanan malam itu dinamakan al-Buraq."),
"faith_151": ("Berapakah jumlah Rukun Islam?", ["Lima", "Tiga", "Enam", "Sepuluh"], "Lima: syahadah, solat, zakat, puasa dan haji."),
"faith_152": ("Apakah Rukun Islam yang pertama?", ["Syahadah (penyaksian iman)", "Puasa", "Haji", "Zakat"], "Seseorang memasuki Islam dengan bersaksi bahawa tiada tuhan selain Allah dan Muhammad ﷺ ialah utusan-Nya."),
"faith_153": ("Berapakah bilangan solat fardu yang dilakukan seorang Muslim setiap hari?", ["Lima", "Tiga", "Tujuh", "Dua"], "Lima solat, tersebar dari subuh hingga malam."),
"faith_154": ("Pada bulan apakah orang Islam berpuasa?", ["Ramadan", "Rejab", "Syaaban", "Syawal"], "«Bulan Ramadan, yang padanya diturunkan al-Quran» (2:185)."),
"faith_155": ("Apakah nama sedekah wajib dalam Islam?", ["Zakat", "Doa", "Zikir", "Tawaf"], "Zakat ialah bahagian harta yang diberikan setiap tahun."),
"faith_156": ("Apakah nama ibadah besar ke Makkah?", ["Haji", "Sa'i", "Zikir", "Sahur"], "Haji ialah ibadah yang dilakukan sekali seumur hidup bagi sesiapa yang mampu."),
"faith_157": ("Berapakah jumlah Rukun Iman (arkanul iman)?", ["Enam", "Empat", "Lima", "Tujuh"], "Beriman kepada Allah, para malaikat-Nya, kitab-kitab-Nya, para rasul-Nya, hari Akhirat, serta qada' dan qadar."),
"faith_158": ("Berapakah bilangan tuhan yang diimani seorang Muslim?", ["Satu sahaja", "Dua", "Tiga", "Banyak"], "«Katakanlah: Dialah Allah, Yang Maha Esa» (112:1)."),
"faith_159": ("Apakah nama yang digunakan orang Islam untuk Tuhan dalam bahasa Arab?", ["Allah", "Malak", "Rasul", "Nabi"], "Allah ialah nama Tuhan Pencipta dalam bahasa Arab."),
"faith_160": ("Apakah nama kitab suci orang Islam?", ["Al-Quran", "Taurat", "Injil", "Zabur"], "Al-Quran ialah kitab yang diwahyukan kepada Nabi Muhammad ﷺ."),
"faith_161": ("Apakah nama Rumah Allah yang dibina di Makkah?", ["Kaabah", "Raudah", "Maqam", "Hijir"], "«Sesungguhnya rumah yang pertama dibina untuk manusia ialah yang di Bakkah» (3:96)."),
"faith_162": ("Apakah yang diucapkan seorang Muslim sebelum mula makan?", ["Bismillah", "Amin", "Subhanallah", "Allahumma"], "Nabi ﷺ mengajar seorang budak lelaki: «Sebutlah Bismillah, dan makanlah dengan tangan kananmu.»"),
"faith_163": ("Bagaimanakah orang Islam memberi salam antara satu sama lain?", ["Assalamualaikum", "Alhamdulillah", "Bismillah", "Allahu Akbar"], "«Assalamualaikum» bermaksud: semoga keselamatan ke atas kamu."),
"faith_164": ("Apakah jawapan kepada «Assalamualaikum»?", ["Waalaikumussalam", "Bismillah", "Amin", "Subhanallah"], "Salam itu dibalas: «dan ke atas kamu juga keselamatan»."),
"faith_165": ("Apakah nama perayaan sejurus selepas bulan Ramadan?", ["Aidilfitri", "Aidiladha", "Lailatul Qadar", "Asyura"], "Aidilfitri, perayaan berbuka puasa selepas sebulan berpuasa."),
"faith_166": ("Apakah nama perayaan korban?", ["Aidiladha", "Aidilfitri", "Maulid", "Lailatul Qadar"], "Aidiladha jatuh pada hari-hari ibadah haji."),
"faith_167": ("Apakah nama makhluk Allah yang sentiasa taat kepada-Nya dan tidak pernah derhaka?", ["Para malaikat", "Jin", "Para nabi", "Para sahabat"], "Para malaikat melaksanakan apa yang Allah perintahkan dan tidak pernah derhaka."),
"faith_168": ("Apakah nama syurga dalam bahasa Arab?", ["Al-Jannah", "As-Solat", "Ad-Du'a", "Al-Azan"], "Al-Jannah, secara harfiah «taman», ialah tempat tinggal yang dijanjikan kepada orang beriman."),
"faith_169": ("Apakah nama bersuci dengan air yang dilakukan sebelum solat?", ["Wuduk", "Tawaf", "Zikir", "Sa'i"], "Wuduk ialah penyucian yang mendahului solat."),
"faith_170": ("Apakah nama bagi satu unit solat?", ["Rakaat", "Surah", "Azan", "Tawaf"], "Satu rakaat mengandungi berdiri, rukuk dan sujud."),
"faith_171": ("Surah manakah yang dibaca dalam setiap rakaat solat?", ["Al-Fatihah", "Al-Ikhlas", "An-Nas", "Al-Kauthar"], "Al-Fatihah, surah pembukaan, dibaca dalam setiap rakaat."),
"faith_172": ("Apakah nama bagi perkara yang dibenarkan dalam Islam?", ["Halal", "Haram", "Sunat", "Fardu"], "Halal bermaksud apa yang dibolehkan."),
"faith_173": ("Apakah nama bagi perkara yang dilarang dalam Islam?", ["Haram", "Halal", "Mubah", "Nafilah"], "Haram bermaksud apa yang tidak dibolehkan."),
"faith_174": ("Daging apakah yang diharamkan oleh al-Quran?", ["Daging babi", "Daging kambing", "Daging lembu", "Daging ayam"], "«Dia mengharamkan kepada kamu bangkai, darah dan daging babi» (2:173)."),
"faith_175": ("Minuman apakah yang al-Quran perintahkan supaya dijauhi?", ["Arak dan setiap yang memabukkan", "Susu", "Madu", "Air hujan"], "«Arak, judi… adalah perbuatan keji, maka jauhilah» (5:90)."),
"faith_176": ("Apakah yang diucapkan orang yang bersin, seperti yang diajar Nabi ﷺ?", ["Alhamdulillah", "Bismillah", "Allahu Akbar", "Amin"], "«Apabila seseorang daripada kamu bersin, hendaklah dia mengucapkan: Alhamdulillah.»"),
"faith_177": ("Bagaimanakah menyebut «solat» dalam bahasa Arab?", ["As-Solat", "As-Saum", "Az-Zakat", "Al-Hajj"], "As-Solat ialah ibadat solat yang dilakukan seorang Muslim."),
"faith_178": ("Apakah nama bagi memohon sesuatu kepada Allah dengan kata-kata sendiri?", ["Doa", "Tawaf", "Azan", "Sa'i"], "Doa ialah permohonan, seruan kepada Allah."),
"faith_179": ("Apakah maksud «Alhamdulillah»?", ["Segala puji bagi Allah", "Allah Maha Besar", "Dengan nama Allah", "Maha Suci Allah"], "Ia ayat kedua Al-Fatihah: «Segala puji bagi Allah, Tuhan sekalian alam» (1:2)."),
"faith_180": ("Apakah maksud perkataan «Islam»?", ["Penyerahan diri kepada Allah", "Kekayaan", "Perjalanan", "Ilmu"], "Islam berasal daripada kata dasar yang bermaksud berserah diri dan berada dalam kesejahteraan."),
"faith_181": ("Apakah maksud perkataan «Muslim»?", ["Orang yang berserah diri kepada Allah", "Orang yang mengembara", "Orang yang mengajar", "Orang yang membina"], "Muslim ialah orang yang berserah diri kepada Allah semata-mata."),
"faith_182": ("Siapakah yang menciptakan langit dan bumi, menurut al-Quran?", ["Allah", "Para malaikat", "Para nabi", "Matahari"], "«Segala puji bagi Allah yang telah menciptakan langit dan bumi» (6:1)."),
"faith_183": ("Berapakah nama Allah yang disebut dalam hadis?", ["Sembilan puluh sembilan", "Sepuluh", "Lima puluh", "Seribu"], "«Allah mempunyai sembilan puluh sembilan nama, seratus kurang satu.»"),
"faith_184": ("Apakah yang dilakukan para malaikat yang digelar «pencatat yang mulia»?", ["Mereka mencatat amalan kita", "Mereka membawa hujan", "Mereka menjaga Kaabah", "Mereka mengajar bahasa Arab"], "«Para pencatat yang mulia, yang mengetahui apa yang kamu lakukan» (82:11-12)."),
"faith_185": ("Malam manakah yang al-Quran gambarkan sebagai lebih baik daripada seribu bulan?", ["Lailatul Qadar", "Malam Jumaat", "Malam hari raya", "Malam pertama Ramadan"], "«Lailatul Qadar lebih baik daripada seribu bulan» (97:3)."),
"faith_186": ("Apakah nama bagi kepercayaan kepada Tuhan yang satu?", ["Tauhid", "Tawaf", "Tayamum", "Tarawih"], "Tauhid ialah keesaan Allah, inti pati risalah setiap nabi."),
"faith_187": ("Apakah nama bagi menyekutukan sesuatu dengan Allah dalam ibadah?", ["Syirik", "Zikir", "Doa", "Sabar"], "Syirik ialah persekutuan: menyembah sesuatu di samping Allah."),
"faith_188": ("Apakah nama hari ketika semua manusia akan dihakimi?", ["Hari Kiamat", "Hari raya", "Hari Jumaat", "Hari pertama Ramadan"], "Yaumul Qiyamah, Hari Kiamat, ketika setiap orang akan melihat amalannya."),
"faith_189": ("Berapakah bilangan bulan dalam setahun menurut al-Quran?", ["Dua belas", "Sepuluh", "Empat belas", "Enam"], "«Sesungguhnya bilangan bulan di sisi Allah ialah dua belas bulan» (9:36)."),
"faith_190": ("Berapakah bilangan sujud dalam satu rakaat?", ["Dua", "Satu", "Tiga", "Empat"], "Setiap rakaat mengandungi dua sujud."),
"quran_151": ("Berapakah jumlah surah dalam al-Quran?", ["Seratus empat belas", "Enam puluh", "Dua ratus", "Tiga puluh"], "Al-Quran mempunyai 114 surah, dari Al-Fatihah hingga An-Nas."),
"quran_152": ("Apakah surah pertama dalam al-Quran?", ["Al-Fatihah", "Al-Baqarah", "An-Nas", "Yasin"], "Al-Fatihah, «Pembukaan», ialah surah yang pertama."),
"quran_153": ("Apakah maksud perkataan «al-Quran»?", ["Bacaan, pembacaan", "Jalan", "Cahaya", "Taman"], "Al-Quran berasal daripada kata dasar yang bermaksud membaca dan melafazkan bacaan."),
"quran_154": ("Dalam tempoh kira-kira berapa tahun al-Quran diturunkan?", ["Kira-kira dua puluh tiga tahun", "Satu malam sahaja", "Seratus tahun", "Tiga tahun"], "Wahyu diturunkan dalam tempoh kira-kira dua puluh tiga tahun."),
"quran_155": ("Apakah nama bagi satu ayat al-Quran?", ["Ayat", "Surah", "Juzuk", "Hadis"], "Setiap kalimat bernombor dalam al-Quran ialah ayat, iaitu satu «tanda»."),
"quran_156": ("Apakah nama bagi satu bab al-Quran?", ["Surah", "Ayat", "Juzuk", "Khutbah"], "Al-Quran dibahagikan kepada surah-surah, setiap satunya mempunyai nama tersendiri."),
"quran_157": ("Apakah surah terpanjang dalam al-Quran?", ["Al-Baqarah", "Al-Fatihah", "Al-Kauthar", "An-Nas"], "Al-Baqarah ialah surah terpanjang dalam al-Quran."),
"quran_158": ("Apakah surah terpendek dalam al-Quran?", ["Al-Kauthar", "Al-Baqarah", "Ali 'Imran", "An-Nisa'"], "Al-Kauthar hanya mempunyai tiga ayat."),
"quran_159": ("Dengan kalimah apakah hampir setiap surah dimulakan?", ["Dengan nama Allah, Yang Maha Pemurah, Yang Maha Penyayang", "Segala puji bagi Allah", "Allah Maha Besar", "Tiada tuhan selain Allah"], "Basmalah membuka 113 daripada 114 surah."),
"quran_160": ("Firman siapakah al-Quran itu?", ["Allah", "Nabi ﷺ", "Malaikat Jibril", "Para sahabat"], "Al-Quran menamakan dirinya «kalam Allah» (firman Allah) dalam 9:6."),
"quran_161": ("Kepada berapa bahagian (juzuk) al-Quran dibahagikan?", ["Tiga puluh", "Sepuluh", "Lima puluh", "Seratus"], "Al-Quran dibahagikan kepada tiga puluh juzuk, satu untuk setiap malam Ramadan."),
"quran_162": ("Surah manakah yang dinamakan sempena nama seorang wanita?", ["Maryam", "Yusuf", "Nuh", "Muhammad"], "Surah ke-19 dinamakan sempena Maryam."),
"quran_163": ("Apakah nama dua surah terakhir, yang dibaca untuk memohon perlindungan?", ["Al-Mu'awwizatain", "Al-Mathani", "Al-Mufassal", "Al-Hawamim"], "Al-Falaq dan An-Nas dinamakan al-Mu'awwizatain, «dua surah perlindungan»."),
"quran_164": ("Dengan perkataan apakah Surah Al-Fatihah dimulakan, selepas basmalah?", ["Al-hamdu", "Qul", "Iqra'", "Inna"], "«Alhamdulillahi rabbil 'alamin» membuka Al-Fatihah."),
"quran_165": ("Apakah nama bagi penjelasan makna al-Quran?", ["Tafsir", "Tajwid", "Hafazan", "Tawaf"], "Tafsir ialah ilmu yang menjelaskan makna ayat-ayat al-Quran."),
"quran_166": ("Surah manakah yang tidak dimulakan dengan basmalah?", ["At-Taubah", "Al-Fatihah", "Al-Ikhlas", "An-Nasr"], "At-Taubah ialah satu-satunya surah yang tidak dibuka dengan basmalah."),
"quran_167": ("Apakah nama bagi orang yang membaca al-Quran dengan suara yang kuat?", ["Qari", "Muazin", "Imam", "Khatib"], "Qari ialah pembaca al-Quran."),
"quran_168": ("Dalam surah manakah terdapat Ayat Kursi?", ["Al-Baqarah", "Al-Kahfi", "Yasin", "Al-Mulk"], "Ayat Kursi ialah ayat ke-255 Surah Al-Baqarah."),
"quran_169": ("Apakah maksud «An-Nur», nama surah ke-24?", ["Cahaya", "Malam", "Angin", "Gunung"], "An-Nur bermaksud «cahaya»."),
"quran_170": ("Surah manakah yang dinamakan «Yang Maha Pemurah»?", ["Ar-Rahman", "Al-Mulk", "Al-Fath", "As-Saff"], "Surah ke-55 dinamakan Ar-Rahman."),
"quran_171": ("Surah manakah yang dinamakan sempena gua?", ["Al-Kahfi", "Al-Fil", "An-Naml", "Al-Baqarah"], "Al-Kahfi bermaksud «gua»."),
"quran_172": ("Apakah maksud «An-Nisa'», nama surah ke-4?", ["Wanita", "Lelaki", "Kanak-kanak", "Musafir"], "An-Nisa' bermaksud «wanita»."),
"quran_173": ("Apakah maksud «Al-Ma'idah», nama surah ke-5?", ["Hidangan", "Gunung", "Besi", "Fajar"], "Al-Ma'idah bermaksud «hidangan»."),
"quran_174": ("Nabi manakah yang namanya menjadi nama surah ke-71?", ["Nuh", "Hud", "Yunus", "Ibrahim"], "Surah ke-71 dinamakan Nuh."),
"quran_175": ("Berapakah jumlah ayat Surah Al-Fatihah?", ["Tujuh", "Tiga", "Sepuluh", "Dua puluh"], "Al-Fatihah mempunyai tujuh ayat."),
"quran_176": ("Di manakah al-Quran menyatakan ia terpelihara?", ["Di Luh Mahfuz (Lauh yang terpelihara)", "Di dalam gua", "Di dalam peti", "Di atas gunung"], "«Bahkan ia al-Quran yang mulia, di Luh Mahfuz» (85:21-22)."),
"quran_177": ("Surah manakah yang dinamakan sempena bulan?", ["Al-Qamar", "Asy-Syams", "An-Najm", "Al-Lail"], "Al-Qamar bermaksud «bulan»."),
"quran_178": ("Surah manakah yang dinamakan sempena Hari Kiamat?", ["Al-Qiyamah", "Al-Fath", "Al-Hasyr", "As-Saff"], "Surah ke-75 dinamakan Al-Qiyamah."),
"quran_179": ("Nabi manakah yang namanya menjadi nama surah ke-14?", ["Ibrahim", "Muhammad ﷺ", "Yusuf", "Hud"], "Surah ke-14 dinamakan Ibrahim."),
"quran_180": ("Apakah maksud «Al-Hadid», nama surah ke-57?", ["Besi", "Emas", "Kayu", "Batu"], "Al-Hadid bermaksud «besi»."),
"virtues_101": ("Bagaimanakah al-Quran menyuruh kita bercakap dengan ibu bapa?", ["Dengan kata-kata yang hormat, malah tidak mengucapkan “ah”", "Lebih kuat daripada mereka", "Dengan sentiasa berdiam diri", "Hanya pada hari Jumaat"], "«Janganlah engkau mengatakan “ah” kepada mereka, dan ucapkanlah kepada mereka kata-kata yang mulia» (17:23)."),
"virtues_102": ("Apakah nama pemberian yang diberikan secara sukarela, kerana kebaikan hati?", ["Sedekah", "Zakat", "Tawaf", "Azan"], "Sedekah ialah pemberian sukarela, sedikit atau banyak."),
"virtues_103": ("Apakah nasihat Nabi ﷺ tentang percakapan, bagi sesiapa yang beriman kepada Allah dan hari Akhirat?", ["Hendaklah dia berkata baik atau diam", "Hendaklah dia banyak bercakap", "Hendaklah dia tidak pernah bercakap", "Hendaklah dia bercakap dengan keluarganya sahaja"], "«Sesiapa yang beriman kepada Allah dan hari Akhirat, hendaklah dia berkata baik atau diam.»"),
"virtues_104": ("Bagaimanakah Nabi ﷺ menyuruh kita melayan jiran?", ["Bermurah hati kepadanya", "Menjauhinya", "Tidak pernah bercakap dengannya", "Menyuruhnya pergi"], "«Sesiapa yang beriman kepada Allah dan hari Akhirat, hendaklah dia memuliakan jirannya.»"),
"virtues_105": ("Bersama siapakah Allah, menurut al-Quran?", ["Bersama orang yang sabar", "Bersama orang yang paling kaya", "Bersama orang yang paling kuat", "Bersama orang yang paling pantas"], "«Sesungguhnya Allah bersama orang yang sabar» (2:153)."),
"virtues_106": ("Apakah yang al-Quran larang dilakukan terhadap anak yatim?", ["Berlaku kasar kepadanya", "Mengajarnya membaca", "Mengajaknya makan", "Bermain dengannya"], "«Maka terhadap anak yatim, janganlah engkau berlaku kasar» (93:9)."),
"virtues_107": ("Percakapan jenis manakah yang al-Quran suruh kita jauhi?", ["Kata-kata dusta", "Kata-kata lembut", "Kata-kata terima kasih", "Kata-kata salam"], "«Dan jauhilah kata-kata dusta» (22:30)."),
"virtues_108": ("Selain kaum kerabat, siapakah lagi yang al-Quran suruh kita berikan haknya?", ["Orang miskin dan musafir", "Raja dan hakim", "Pedagang", "Penyair"], "«Berikanlah kepada kaum kerabat haknya, juga kepada orang miskin dan musafir» (17:26)."),
"virtues_109": ("Apakah yang Allah janjikan kepada orang yang bersyukur kepada-Nya?", ["Menambahkan nikmat kepadanya", "Menjadikannya pengembara", "Menjadikannya terkenal", "Menjadikannya raja"], "«Jika kamu bersyukur, nescaya Aku akan menambah nikmat kepada kamu» (14:7)."),
"virtues_110": ("Bagaimanakah menyebut «kesabaran» dalam bahasa Arab?", ["As-Sabr", "Asy-Syukr", "As-Sidq", "Al-Haya'"], "As-Sabr ialah ketabahan dalam kesusahan dan dalam ketaatan."),
"faith_191": ("Apakah nama bagi mengingati Allah, dengan mengulang-ulang pujian kepada-Nya?", ["Zikir", "Haji", "Sa'i", "Tayamum"], "Zikir ialah mengingati Allah dengan lidah dan hati."),
"faith_192": ("Apakah bulan pertama dalam tahun Islam?", ["Muharam", "Ramadan", "Syawal", "Rejab"], "Tahun Hijrah dimulakan dengan bulan Muharam."),
"faith_193": ("Apakah nama bagi kembali kepada Allah selepas melakukan dosa?", ["Taubat", "Tawaf", "Tajwid", "Tarawih"], "Taubat ialah penyesalan: menyesal, berhenti, dan kembali kepada Allah."),
"faith_194": ("Siapakah yang memberi rezeki kepada setiap makhluk di bumi?", ["Allah", "Raja-raja", "Para pedagang", "Para malaikat"], "«Tiada satu pun makhluk yang bergerak di bumi melainkan Allah yang menanggung rezekinya» (11:6)."),
"faith_195": ("Di kota manakah ibadah haji dilakukan?", ["Di Makkah", "Di Madinah", "Di Baitulmaqdis", "Di Kaherah"], "Haji dilakukan di Makkah dan tempat-tempat sucinya."),
"faith_196": ("Apakah nama bagi orang yang mengerjakan haji?", ["Haji (jemaah haji)", "Imam", "Qari", "Muazin"], "Orang yang mengerjakan haji dipanggil haji."),
"faith_197": ("Apakah yang Allah ketahui, menurut al-Quran, walaupun disembunyikan?", ["Apa yang ada di dalam hati", "Hanya amalan yang nampak", "Hanya kata-kata yang diucapkan", "Tiada yang tersembunyi"], "«Sama ada kamu sembunyikan apa yang ada di dalam dada kamu atau kamu zahirkan, Allah mengetahuinya» (3:29)."),
"faith_198": ("Kepada siapakah puasa diwajibkan, menurut al-Quran?", ["Kepada orang beriman, sebagaimana kepada orang sebelum mereka", "Hanya kepada musafir", "Hanya kepada ulama", "Hanya kepada kanak-kanak"], "«Wahai orang yang beriman, diwajibkan ke atas kamu berpuasa sebagaimana diwajibkan ke atas orang sebelum kamu» (2:183)."),
"faith_199": ("Apakah nama solat berjemaah yang besar pada hari Jumaat?", ["Solat Jumaat", "Solat hari raya", "Solat witir", "Solat Dhuha"], "Solat Jumaat menghimpunkan orang Islam pada tengah hari Jumaat."),
"faith_200": ("Bagaimanakah menyebut «puasa» dalam bahasa Arab?", ["As-Saum", "As-Solat", "Az-Zakat", "Al-Azan"], "As-Saum ialah puasa, Rukun Islam yang keempat."),
}
